using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Interop;
using System.Windows.Media;
using DogSC.Windows;
using D=System.Drawing;

namespace DogSC.Replica {
 static partial class CapturePerformanceTests {
  public static async Task RunSmoothness(){
   string folder=Path.Combine(Media.Root,"bin","smoothness-test",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var canvas=new Canvas {Background=UI.Brush("#193E51")};var square=new Border {Width=160,Height=120,Background=UI.Brush("#C5F4DD")};canvas.Children.Add(square);var marker=new Border {Width=128,Height=128};canvas.Children.Add(marker);Canvas.SetTop(marker,30);int sequence=0;var surface=new Window {Title="DogSC synthetic smoothness benchmark",Width=Math.Min(1800,SystemParameters.WorkArea.Width),Height=Math.Min(1100,SystemParameters.WorkArea.Height),WindowStartupLocation=WindowStartupLocation.CenterScreen,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,Content=canvas,Topmost=true,ShowInTaskbar=false};var motion=Stopwatch.StartNew();var stalls=new List<double>();double previous=0;
   EventHandler animate=(s,e)=>{double now=motion.Elapsed.TotalMilliseconds;if(previous>0)stalls.Add(now-previous);previous=now;sequence++;marker.Background=new SolidColorBrush(Color.FromRgb((byte)(sequence%256),(byte)(sequence*13%256),(byte)(sequence*37%256)));Canvas.SetLeft(marker,Math.Max(0,canvas.ActualWidth-160));Canvas.SetLeft(square,(Math.Sin(now/600)+1)*Math.Max(0,canvas.ActualWidth-200)/2+20);Canvas.SetTop(square,(Math.Cos(now/700)+1)*Math.Max(0,canvas.ActualHeight-180)/2+20);};
   var report=new System.Text.StringBuilder();try{surface.Show();CompositionTarget.Rendering+=animate;await Task.Delay(300);var hwnd=new WindowInteropHelper(surface).Handle;RECT rect;if(!GetClientRect(hwnd,out rect))throw new Exception("Synthetic bounds unavailable");var origin=new Native.Point();ClientToScreen(hwnd,ref origin);var area=new D.Rectangle(origin.X,origin.Y,(rect.Right-rect.Left)/2*2,(rect.Bottom-rect.Top)/2*2);
    await CaptureEngine.Prewarm();foreach(int fps in new[]{60,90})for(int round=0;round<2;round++)foreach(bool legacy in round==0?new[]{true,false}:new[]{false,true}){string label="trial"+(round+1)+"-"+(legacy?"before":"after")+"-"+fps;string output=Path.Combine(folder,label+".mp4");CaptureSession session=null;try{session=await CaptureEngine.StartBenchmark(area,fps,output,legacy);stalls.Clear();previous=0;double cpu=session.CpuSeconds,start=session.Clock.Elapsed.TotalSeconds;await Task.Delay(4000);double load=(session.CpuSeconds-cpu)/(session.Clock.Elapsed.TotalSeconds-start);var timing=stalls.OrderBy(v=>v).ToArray();double p95=timing.Length>0?timing[(int)((timing.Length-1)*.95)]:0;await CaptureEngine.Finish(session,output);var doc=await Task.Run(()=>StudioMedia.Import(output));if(doc.Width!=area.Width||doc.Height!=area.Height||Math.Abs(doc.FrameRate-fps)>.1||doc.Duration<3.5)throw new Exception("Capture lost resolution, rate or elapsed time: "+label);using(var data=new MemoryStream(StudioMedia.Frame(output,.2,area.Width)))using(var image=new D.Bitmap(data)){var pixel=image.GetPixel(4,4);if(Math.Abs(pixel.R-25)+Math.Abs(pixel.G-62)+Math.Abs(pixel.B-81)>24)throw new Exception("GPU conversion changed background colors: "+pixel);}
      string unique=await Task.Run(()=>MotionFrames(output));report.AppendLine(label+": "+doc.Width+"x"+doc.Height+" @ "+doc.FrameRate+" FPS; "+session.Backend+"; recording CPU cores "+load.ToString("F3")+"; UI render interval p95 "+p95.ToString("F1")+" ms; "+unique+"; encoder duplicated "+session.Duplicated+" / dropped "+session.Dropped);File.WriteAllText(Path.Combine(folder,"measurements.txt"),report.ToString());
     }finally{if(session!=null){try{if(!session.Process.HasExited)session.Process.Kill();}catch{}session.Process.Dispose();}}}
    File.WriteAllText(Path.Combine(Media.Root,"bin","smoothness-results.txt"),"PASS: same native resolution and chosen 60/90 FPS, correct crop/colors and elapsed time; animated opaque synthetic window only.\n"+report+"Measurements are local short synthetic runs, not a guarantee for all desktops.\nArtifacts: "+folder+"\n");
   }finally{CompositionTarget.Rendering-=animate;surface.Close();}
  }
  static string MotionFrames(string path){using(var p=Media.Start("ffmpeg","-v error -i "+Media.Q(path)+" -ss 1 -t 2 -an -vf scale=96:60 -f framemd5 pipe:1",true)){var error=p.StandardError.ReadToEndAsync();string result=p.StandardOutput.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new Exception(error.Result);var frames=result.Split('\n').Where(s=>!s.StartsWith("#")&&s.Contains(",")).Select(s=>s.Substring(s.LastIndexOf(',')+1).Trim()).ToArray();int repeated=0,longest=0,run=0;for(int i=1;i<frames.Length;i++){run=frames[i]==frames[i-1]?run+1:0;if(run>0)repeated++;longest=Math.Max(longest,run);}return "decoded "+frames.Length+" frames / repeated "+repeated+" / longest repeated run "+longest;}}
 }
 public partial class Studio {
  public async Task VerifyRecordingWork(string folder){
   Directory.CreateDirectory(folder);string source=Path.Combine(folder,"source.mp4");await Task.Run(()=>StudioMedia.Run("-v error -y -loop 1 -i "+Media.Q(Path.GetFullPath(Path.Combine(Media.Root,"../Resources/Onboarding/SoftLight.png")))+" -t 2 -vf scale=1280:720 -r 30 -c:v libx264 -preset ultrafast -pix_fmt yuv420p "+Media.Q(source),CancellationToken.None));await Load(source);Play();await Task.Delay(80);await SuspendForRecording();if(playing||rendering||thumbnailJobs!=0||playbackJobs!=0)throw new Exception("Editor work still running during recording");var image=preview.Source;Play();LoadThumbnails();await PreviewNow();await Task.Delay(80);if(playing||rendering||thumbnailJobs!=0||preview.Source!=image)throw new Exception("Editor background work restarted during recording");
   var report=new System.Text.StringBuilder();foreach(int fps in new[]{30,60,90}){var session=new CaptureSession();session.Clock.Start();using(var sampler=new PointerCaptureSampler(IntPtr.Zero,new D.Rectangle(0,0,16,16),fps,17,4,session)){Thread.Sleep(500);var samples=sampler.Stop();if(sampler.Failure!=null)throw sampler.Failure;if(sampler.RawSamples<fps*.3||samples.Count==0||samples.Any(p=>p.Segment!=17||p.Time<4))throw new Exception("Pointer sampling stalled behind UI at "+fps+" FPS");int count=sampler.RawSamples;await Task.Delay(80);if(sampler.RawSamples!=count)throw new Exception("Stopped pointer sampler continued");report.AppendLine("PASS: UI blocked 500 ms at "+fps+" FPS; background samples "+count+", stored "+samples.Count+", late "+sampler.LateSamples+"; "+sampler.Timing+"; segment offset preserved and stopped sampler frozen.");}}
   ResumeAfterRecording(false);await PreviewNow();if(preview.Source==null||recordingWorkSuspended)throw new Exception("Editor preview failed to resume");
   string incomingFolder=Path.Combine(folder,"incoming");Directory.CreateDirectory(incomingFolder);string incoming=Path.Combine(incomingFolder,"source.mp4");File.Copy(source,incoming);var existing=Doc;existing.Name="Unsaved original";dirty=true;bool cancelled=false;var answer=new System.Windows.Threading.DispatcherTimer {Interval=TimeSpan.FromMilliseconds(80)};answer.Tick+=(s,e)=>{var card=Application.Current.Windows.OfType<AppDialogWindow>().FirstOrDefault(w=>w.IsLoaded);if(card!=null){cancelled=true;answer.Stop();DialogTestDriver.Click(card.Actions["cancel"]);}};answer.Start();try{await Recorded(incoming,new List<PointerSample>{new PointerSample {Time=.1,X=.3,Y=.4,Click=true}});}finally{answer.Stop();}string project=Path.Combine(incomingFolder,"project.dogscwin");if(!cancelled||Doc!=existing||!dirty||!File.Exists(project))throw new Exception("Cancelling project switch lost recording or current edits");var saved=EditDocument.Deserialize(File.ReadAllText(project));if(saved.Source!=incoming||saved.Pointer.Count!=1||!saved.IndependentCursor)throw new Exception("Cancelled switch lost cursor metadata");report.AppendLine("PASS: recording project and independent cursor saved before cancelable project switch; original unsaved edits retained.");
   dirty=false;File.WriteAllText(Path.Combine(Media.Root,"bin","recording-work-results.txt"),"PASS: playback, preview decoder and thumbnail jobs quiesced before recording; remain suspended until completion; original preview resumes.\n"+report);
  }
 }
}
